package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim of a person on a sheet. Mutable so an Apply step can change it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;

    private String editedBy;
    private Integer settleBatch;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate roundOn;
    private LocalDate dueFrom;
    private int terms;
    private LocalDate dueBy;
    private LocalDate deferredUntil;
    private int proofs;
    private String splitFrom;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private String ref;
    private String tags;
    private String voidReason;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy,
            boolean stated, BigDecimal statedDue, String corrects) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
        this.corrects = corrects;
        this.roundOn = date;
    }

    /** The date the claim's due-by counts from: its date when it was added, kept when the date later changes. */
    public LocalDate getDueFrom() {
        return dueFrom;
    }

    public void setDueFrom(LocalDate dueFrom) {
        this.dueFrom = dueFrom;
    }

    /** The terms the claim was fixed with when it was added: those in force on its date for its person, in business days. */
    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    /**
     * The date the claim is due by: the terms-th business day after its due-from date (skipping Saturdays, Sundays and
     * the sheet's holidays as they stand now), worked out whenever the claim is read.
     */
    public LocalDate getDueBy() {
        return dueBy;
    }

    public void setDueBy(LocalDate dueBy) {
        this.dueBy = dueBy;
    }

    /** The date the claim was last deferred until; null when it was never deferred. */
    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    /** The number of the claim this one was split off; null when it was not split off one. */
    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    /** Whether the claim was added while the period containing its date was soft-closed. */
    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    /** The last sheet-today a reminder was written for the claim; null when never reminded. */
    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

    /** The claim's external reference; null when it has none. */
    public String getRef() {
        return ref;
    }

    public void setRef(String ref) {
        this.ref = ref;
    }

    /** The claim's tags, sorted and joined by commas; null when it has none. */
    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    /** The reason the claim was voided with, from the sheet's list; null when none was given. */
    public String getVoidReason() {
        return voidReason;
    }

    public void setVoidReason(String voidReason) {
        this.voidReason = voidReason;
    }

    /** Keep {@code amount} of the claim, the rest split off: it loses any figure a statement bound it to. */
    public void keep(BigDecimal amount) {
        this.amount = amount;
        this.stated = false;
        this.statedDue = null;
    }

    /** How many proofs the claim carries. */
    public int getProofs() {
        return proofs;
    }

    public void setProofs(int proofs) {
        this.proofs = proofs;
    }

    /** Whether the claim is deferred as of {@code today}: OPEN, and deferred until a date after today. Until then it
     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    /** The date the claim's live figures round by: its own, or for a correction the date of the claim it corrects. */
    public LocalDate getRoundOn() {
        return roundOn;
    }

    public void setRoundOn(LocalDate roundOn) {
        this.roundOn = roundOn;
    }

    public long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public long getPersonId() {
        return personId;
    }

    /** Move the claim to another person: it loses any figure a statement bound it to. */
    public void moveTo(long personId) {
        this.personId = personId;
        this.stated = false;
        this.statedDue = null;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        if (corrects == null) {
            this.roundOn = date;
        }
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    /** The number given when the claim was opened; null for a draft (or a claim voided as a draft); a voided claim keeps its number, never reused. */
    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    /** The due fixed when the claim was settled; null when not settled or settled without a rate. */
    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    /** The signed-in user who opened the claim; null when it was never opened. */
    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    /** The number of the bulk settle batch that settled the claim; null when no batch settled it. */
    public Integer getSettleBatch() {
        return settleBatch;
    }

    public void setSettleBatch(Integer settleBatch) {
        this.settleBatch = settleBatch;
    }

    /** The signed-in user who last edited the claim through its form or amount entry; null when never edited. */
    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    /** Whether the person's last statement bound the claim to a figure. */
    public boolean isStated() {
        return stated;
    }

    /** Whether the last statement's figure is the claim's: it was stated, and is not PENDING (a PENDING claim shows and
     *  totals its live figure; rejected back to OPEN, it is bound again). */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /** The figure the last statement bound the claim to; null when bound without one (n/a) or not bound. */
    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** The number of the SETTLED claim this correction corrects; null for a claim that is not a correction. */
    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    /** Whether the claim is a correction: its amount is below 0.00 (no floor and no late charge apply). */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    /**
     * The claim's rate figure: its amount times the rate, rounded to two decimals by the rounding given. The floor is
     * not applied here; it comes last, after the late charge (see LateCharge). Null without a rate.
     */
    public BigDecimal figureAt(BigDecimal rate, java.math.RoundingMode rounding) {
        if (rate == null) {
            return null;
        }
        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.access.LateCharge;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures, as the screen shows them: a person's claimed is their counting claims' amounts added up;
 * their due-total is those claims' figures added up (a claim's figure: its settled due, else the figure a statement
 * bound it to, else its amount times the rate in force on its date of the grade in force on its date, rounded half up when the claim rounds by a date before the sheet's policy date, else half to even;
 * none without a rate) with its late charge added on top while it is overdue, and then — unless it is settled or a correction — at least the sheet's floor in force on its date, n/a when their grade on the sheet's today has no rate then and no counting claim keeps a settled or bound
 * figure or one at another grade, and at most the sheet's cap in force on its today (an n/a one is not capped); their overdue-total is the figures (late charge included) of
 * those of their claims that are OPEN or PENDING and past their due-by plus their grade's grace on the sheet's today, added up (uncapped). After a change, records one ROLLUP line per person whose figures (overdue-total included) it moved,
 * then a TOTALS line when any of the sheet's three totals moved. The sheet's due-total and overdue-total leave out the
 * single highest and the single lowest person's figure when three or more people have one (an n/a due-total is none). A claim deferred past the sheet's today counts in none of these. A person's OPEN and PENDING claims dated within one of their holds count in none of these, unless a statement
 * binds them; their other claims still do. So too, from the day their retirement date is reached (the sheet's today on or
 * after it), do none of a retired person's OPEN and PENDING claims, unless a statement binds them.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final ClaimLogRepository log;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, ClaimLogRepository log, Audit audit) {
        this.log = log;
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    public RollupSnapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.list(sheetId);
        List<Claim> sheetClaims = claims.list(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        BigDecimal cap = late.settings().cap(today);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person p : people.list(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            boolean kept = false;
            for (Claim c : sheetClaims) {
                if (c.getPersonId() != p.getId() || !counts(c, p, today)) {
                    continue;
                }
                claimed = claimed.add(c.getAmount().setScale(2));
                kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
                String grade = p.gradeOn(c.getDate());
                BigDecimal figure = late.due(c, figure(c, grade, sheetRates, late));
                // A figure at a grade other than today's does not hang on today's grade having a rate; nor does one
                // dated on or before today, whose rate may have ended since.
                kept |= figure != null && (!grade.equals(p.getGrade()) || !c.getDate().isAfter(today));
                if (figure != null) {
                    due = due.add(figure);
                    if (late.overdue(c)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            BigDecimal personDue = SettingRepository.capped(
                    kept || rateOn(sheetRates, p.getGrade(), today) != null ? due : null, cap);
            figures.put(p.getId(), new Figures(p.getName(), claimed, personDue, overdue));
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue);
            if (personDue != null) {
                dues.add(personDue);
            }
        }
        return new RollupSnapshot(figures, claimedTotal, trimmed(dues), trimmed(overdues));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    static BigDecimal trimmed(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(ZERO, BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
        return sum.subtract(max).subtract(min);
    }

    /**
     * The due-total of the claims dated from..to (inclusive) counting by their status at the end of {@code to}, as the
     * screen shows a period's: each claim's figure now (with its late charge) added up, a claim without one adding nothing.
     */
    public BigDecimal dueBetween(String sheetId, LocalDate from, LocalDate to) {
        return dueBetweenByPerson(sheetId, from, to).values().stream().reduce(ZERO, BigDecimal::add);
    }

    /**
     * Each person's due-total for the dates from..to (inclusive), by person id, every person on the sheet included
     * (0.00 when none of their counting claims is due by a date there: a claim belongs to the period of its due-by): their counting claims' figures (with late charge) added up.
     * A claim counts by the status its log records at the end of {@code to} (one added after it does not count); its
     * figure is the one it shows now, and a deferred or held claim is left out as the live totals leave it out.
     */
    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.list(sheetId);
        LocalDate today = sheets.today(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        Map<Long, Person> byId = new LinkedHashMap<>();
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person p : people.list(sheetId)) {
            byId.put(p.getId(), p);
            totals.put(p.getId(), ZERO);
        }
        Map<Long, ClaimStatus> asOf = log.statusesAsOf(sheetId, to);
        for (Claim c : claims.list(sheetId)) {
            Person p = byId.get(c.getPersonId());
            ClaimStatus then = asOf.get(c.getId());
            if (p == null || then == null || !countsAs(c, then, p, today) || c.getDueBy().isBefore(from)
                    || c.getDueBy().isAfter(to)) {
                continue;
            }
            BigDecimal figure = late.due(c, figure(c, p.gradeOn(c.getDate()), sheetRates, late));
            if (figure != null) {
                totals.merge(p.getId(), figure, BigDecimal::add);
            }
        }
        return totals;
    }

    /** The claim's due as the screen shows it now: its figure with its late charge on top; null (n/a) without one. */
    public BigDecimal dueOf(Claim claim) {
        String sheetId = claim.getSheetId();
        Person p = people.find(sheetId, claim.getPersonId());
        if (p == null) {
            return null;
        }
        LateCharge late = settings.lateCharge(sheetId, sheets.today(sheetId));
        return late.due(claim, figure(claim, p.gradeOn(claim.getDate()), rates.list(sheetId), late));
    }

    /** Record the figures the change moved, from {@code before} to the sheet's figures now. */
    public void record(String sheetId, RollupSnapshot before, ChangedBy by) {
        RollupSnapshot after = snapshot(sheetId);
        List<String> lines = new ArrayList<>();
        String who = " sheet=" + sheetId + " by=" + by.name();
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            if (now.movedFrom(before.people().get(e.getKey()))) {
                lines.add("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed().toPlainString()
                        + " due-total=" + show(now.dueTotal()) + " overdue-total=" + now.overdueTotal().toPlainString());
            }
        }
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
                || !after.overdueTotal().equals(before.overdueTotal())) {
            lines.add("TOTALS" + who + " claimed-total=" + after.claimedTotal().toPlainString() + " due-total="
                    + after.dueTotal().toPlainString() + " overdue-total=" + after.overdueTotal().toPlainString());
        }
        lines.forEach(audit::record);
    }

    /** Whether the claim counts in the live totals: its person's OPEN and PENDING claims dated within a hold do not,
     *  unless a statement binds them, nor does a claim deferred past the sheet's today; their other ones do. */
    private static boolean counts(Claim claim, Person person, LocalDate today) {
        return claim.getStatus().counts() && !held(claim, person, today) && !claim.isDeferredOn(today);
    }

    /** Whether the claim counts as it would in the live totals were its status {@code then}. */
    private static boolean countsAs(Claim claim, ClaimStatus then, Person person, LocalDate today) {
        // Held as the live totals hold it: by its status now, not the one it had then.
        boolean held = claim.getStatus().isOpen() && !claim.isStated()
                && (person.heldOn(claim.getDate()) || person.retiredOn(today));
        return then.counts() && !held && !claim.isDeferredOn(today);
    }

    /** Whether a hold leaves the claim out: it is OPEN or PENDING, unbound, and dated within one of its person's holds
     *  or its person's retirement date is reached on the sheet's today. */
    public static boolean held(Claim claim, Person person, LocalDate today) {
        return claim.getStatus().isOpen() && !claim.isBound()
                && (person.heldOn(claim.getDate()) || person.retiredOn(today));
    }

    private static String show(BigDecimal figure) {
        return figure == null ? "n/a" : figure.toPlainString();
    }

    /** A claim's figure: its settled due, else the figure a statement bound, else its rate figure (the floor comes later, after the late charge). */
    private static BigDecimal figure(Claim claim, String grade, List<Rate> sheetRates, LateCharge late) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue().setScale(2);
        }
        if (claim.isBound()) {
            return claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2);
        }
        BigDecimal rate = rateOn(sheetRates, grade, claim.getDate());
        return claim.figureAt(rate, late.rounding(claim));
    }

    /**
     * The grade's rate in force on the date: the latest from-date on or before it, none counting as the earliest; none
     * when the date is after that rate's to-date.
     */
    private static BigDecimal rateOn(List<Rate> sheetRates, String grade, LocalDate on) {
        Rate found = null;
        for (Rate r : sheetRates) {
            if (!r.grade().equals(grade) || (r.from() != null && r.from().isAfter(on))) {
                continue;
            }
            if (found == null || (r.from() != null && (found.from() == null || r.from().isAfter(found.from())))) {
                found = r;
            }
        }
        return found == null || (found.to() != null && found.to().isBefore(on)) ? null : found.rate();
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import net.officefloor.hq.app.holiday.HolidayRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** The claims on each sheet; ids are assigned in the order claims are added, and claims are listed newest first (a moved claim as its new person's newest). */
@Repository
public class ClaimRepository {

    // A correction rounds by the date of the claim it corrects (a claim of the same person, by number).
    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, opened_by, stated, stated_due, corrects, due_from, terms, due_by, deferred_until, proofs, split_from, late_entry, reminded_on, ref, tags, void_reason, edited_by, settle_batch,"
            + " (SELECT o.claim_date FROM claim o WHERE o.sheet_id = claim.sheet_id AND o.person_id = claim.person_id"
            + " AND o.claim_number = claim.corrects) AS corrected_date";

    private static final RowMapper<Claim> ROW = (rs, n) -> {
        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"),
                rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
                rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
                rs.getString("claim_number"), rs.getBigDecimal("settled_due"),
                rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"),
                rs.getString("corrects"));
        claim.setDueFrom(rs.getObject("due_from", LocalDate.class));
        claim.setTerms(rs.getInt("terms"));
        claim.setDueBy(rs.getObject("due_by", LocalDate.class));
        claim.setDeferredUntil(rs.getObject("deferred_until", LocalDate.class));
        claim.setProofs(rs.getInt("proofs"));
        claim.setSplitFrom(rs.getString("split_from"));
        claim.setLateEntry(rs.getBoolean("late_entry"));
        claim.setRemindedOn(rs.getObject("reminded_on", LocalDate.class));
        claim.setRef(rs.getString("ref"));
        claim.setTags(rs.getString("tags"));
        claim.setVoidReason(rs.getString("void_reason"));
        claim.setEditedBy(rs.getString("edited_by"));
        claim.setSettleBatch(rs.getObject("settle_batch", Integer.class));
        LocalDate corrected = rs.getObject("corrected_date", LocalDate.class);
        if (corrected != null) {
            claim.setRoundOn(corrected);
        }
        return claim;
    };

    private final JdbcTemplate jdbc;

    private final HolidayRepository holidays;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
        this.holidays = new HolidayRepository(jdbc);
    }

    /**
     * Work out the due-by of each claim not yet fixed (added before due-bys were stored) from the date it counts from,
     * its terms and its sheet's holidays as they stand now.
     */
    private List<Claim> due(List<Claim> claims) {
        Map<String, Set<LocalDate>> bySheet = new HashMap<>();
        for (Claim claim : claims) {
            if (claim.getDueBy() != null) {
                continue;
            }
            Set<LocalDate> off = bySheet.computeIfAbsent(claim.getSheetId(), holidays::set);
            claim.setDueBy(HolidayRepository.businessDay(claim.getDueFrom(), claim.getTerms(), off));
        }
        return claims;
    }

    /** The person's claims, newest first. */
    public List<Claim> listOf(String sheetId, long personId) {
        return due(jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC", ROW,
                sheetId, personId));
    }

    /** Bind the claim to a figure (null: n/a), or unbind it when not {@code stated}. */
    public void bind(long id, boolean stated, BigDecimal statedDue) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE id = ?", stated, statedDue, id);
    }

    /** Unbind every claim of the person from its statement figure, so each is live again. */
    public void unbindAllOf(String sheetId, long personId) {
        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ?",
                sheetId, personId);
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return due(jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY listed DESC", ROW, sheetId));
    }

    /** Whether the person has a SETTLED claim with this number on the sheet. */
    public boolean settledNumbered(String sheetId, long personId, String number) {
        return jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ? AND claim_number = ? AND status = ?",
                Integer.class, sheetId, personId, number, ClaimStatus.SETTLED.name()) > 0;
    }

    public Claim find(String sheetId, long id) {
        return due(jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id))
                .stream().findFirst().orElse(null);
    }

    /** Whether a claim on the sheet other than {@code exceptId} carries the reference, comparing without regard to case. */
    public boolean refUsed(String sheetId, String ref, long exceptId) {
        return jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
                Integer.class, sheetId, ref, exceptId) > 0;
    }

    /** Add a draft claim without a reference. */
    public Claim insert(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            int terms) {
        return insert(sheetId, personId, amount, date, note, corrects, null, null, terms);
    }

    /** Add a draft claim, its due-by counting {@code terms} business days from its date for good, with its reference and tags (null: none). */
    public Claim insert(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            String ref, String tags, int terms) {
        long listed = nextListed(sheetId);
        LocalDate dueBy = holidays.dueBy(sheetId, date, terms);
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, listed, due_from, terms, ref, tags, due_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setString(6, corrects);
            ps.setLong(7, listed);
            ps.setDate(8, Date.valueOf(date));
            ps.setInt(9, terms);
            ps.setString(10, ref);
            ps.setString(11, tags);
            ps.setDate(12, Date.valueOf(dueBy));
            return ps;
        }, keys);
        Claim claim = new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null, false, null, corrects);
        claim.setDueFrom(date);
        claim.setTerms(terms);
        claim.setDueBy(dueBy);
        claim.setRef(ref);
        claim.setTags(tags);
        used(sheetId, tags);
        return claim;
    }

    /**
     * Re-fix, for a holiday just added on {@code holiday}, the due-by of every claim on the sheet that is neither SETTLED
     * nor VOID and is due on or after it: each is worked out again from the claim's date with the terms it was fixed
     * with, over the sheet's holidays as they stand now.
     */
    public void refix(String sheetId, LocalDate holiday) {
        Set<LocalDate> off = holidays.set(sheetId);
        for (Claim claim : list(sheetId)) {
            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                    || claim.getDueBy().isBefore(holiday)) {
                continue;
            }
            LocalDate dueBy = HolidayRepository.businessDay(claim.getDate(), claim.getTerms(), off);
            jdbc.update("UPDATE claim SET due_by = ? WHERE id = ?", Date.valueOf(dueBy), claim.getId());
        }
    }

    /** Mark the claim, just added, a late entry: its period was soft-closed when it was added. */
    public void markLate(Claim claim) {
        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE id = ?", claim.getId());
        claim.setLateEntry(true);
    }

    /**
     * Split {@code amount} off the OPEN claim: it keeps the rest, unbound from any statement figure, and a new OPEN claim
     * with the amount, its date, note and tags, opened by {@code openedBy}, due by {@code terms} business days from its date and split from its number is
     * listed as its person's newest. Null when the claim was no longer OPEN at its amount: another user changed it.
     */
    public Claim split(Claim claim, BigDecimal amount, String openedBy, int terms) {
        BigDecimal rest = claim.getAmount().subtract(amount);
        if (jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL WHERE id = ? AND status = ? AND amount = ?",
                rest, claim.getId(), ClaimStatus.OPEN.name(), claim.getAmount()) != 1) {
            return null;
        }
        claim.keep(rest);
        Claim into = insert(claim.getSheetId(), claim.getPersonId(), amount, claim.getDate(), claim.getNote(), null, null,
                claim.getTags(), terms);
        into.setStatus(ClaimStatus.OPEN);
        into.setOpenedBy(openedBy);
        into.setSplitFrom(claim.getNumber());
        jdbc.update("UPDATE claim SET status = ?, opened_by = ?, split_from = ? WHERE id = ?",
                ClaimStatus.OPEN.name(), openedBy, claim.getNumber(), into.getId());
        return into;
    }

    public void update(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, corrects = ?, ref = ?, tags = ?, edited_by = ? WHERE id = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getCorrects(), claim.getRef(), claim.getTags(),
                claim.getEditedBy(), claim.getId());
        used(claim.getSheetId(), claim.getTags());
    }

    /** Note the tags (joined by commas; null: none) as used on the sheet, for good. */
    private void used(String sheetId, String tags) {
        if (tags == null) {
            return;
        }
        for (String tag : tags.split(",")) {
            jdbc.update("MERGE INTO claim_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", sheetId, tag);
        }
    }

    /** Every tag ever used on the sheet's claims, sorted. */
    public List<String> tagsUsed(String sheetId) {
        return jdbc.queryForList("SELECT tag FROM claim_tag WHERE sheet_id = ? ORDER BY tag", String.class, sheetId);
    }

    /** Defer the claim until its deferred-until date. Whether it was still OPEN: another user may have moved it. */
    public boolean defer(Claim claim) {
        return jdbc.update("UPDATE claim SET deferred_until = ? WHERE id = ? AND status = ?",
                Date.valueOf(claim.getDeferredUntil()), claim.getId(), ClaimStatus.OPEN.name()) == 1;
    }

    /**
     * Remind the claim on {@code today}. Whether it was still in its status and not yet reminded that day: another user
     * may have changed or reminded it.
     */
    public boolean remind(Claim claim, LocalDate today) {
        boolean reminded = jdbc.update("UPDATE claim SET reminded_on = ? WHERE id = ? AND status = ?"
                + " AND (reminded_on IS NULL OR reminded_on <> ?)", Date.valueOf(today), claim.getId(),
                claim.getStatus().name(), Date.valueOf(today)) == 1;
        if (reminded) {
            claim.setRemindedOn(today);
        }
        return reminded;
    }

    /**
     * Re-date the claim to {@code date}, its due-by still counting from the date it was added and any statement figure. Whether it was still in its status
     * at its old date: another user may have changed it.
     */
    public boolean redate(Claim claim, LocalDate date) {
        boolean redated = jdbc.update("UPDATE claim SET claim_date = ? WHERE id = ? AND status = ? AND claim_date = ?",
                Date.valueOf(date), claim.getId(), claim.getStatus().name(), Date.valueOf(claim.getDate())) == 1;
        if (redated) {
            claim.setDate(date);
        }
        return redated;
    }

    /** Raise the claim's proofs count by one. Whether it was still in its status: another user may have moved it. */
    public boolean addProof(Claim claim) {
        boolean added = jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE id = ? AND status = ?",
                claim.getId(), claim.getStatus().name()) == 1;
        if (added) {
            claim.setProofs(jdbc.queryForObject("SELECT proofs FROM claim WHERE id = ?", Integer.class, claim.getId()));
        }
        return added;
    }

    /**
     * Move the claim from {@code from} to its status, number, settled due and opener. Whether it was still {@code from}:
     * the row is locked by the first of two users changing it, so the other one finds it moved.
     */
    public boolean updateStatus(Claim claim, ClaimStatus from) {
        return jdbc.update("UPDATE claim SET status = ?, claim_number = ?, settled_due = ?, opened_by = ?, void_reason = ? WHERE id = ? AND status = ?",
                claim.getStatus().name(), claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getVoidReason(), claim.getId(), from.name()) == 1;
    }

    /**
     * Move the claim to its person, unbound from any statement figure and listed as that person's newest claim. Whether
     * it was still in its status: the first of two users changing it locks the row, so the other one finds it moved.
     */
    public boolean reassign(Claim claim, long personId) {
        boolean moved = jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, listed = ?"
                + " WHERE id = ? AND status = ?", personId, nextListed(claim.getSheetId()), claim.getId(),
                claim.getStatus().name()) == 1;
        if (moved) {
            claim.moveTo(personId);
        }
        return moved;
    }

    /** Take the sheet's next listing key: a claim added or moved is listed before every claim listed earlier. */
    private long nextListed(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE "
                + "(UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)", Long.class, sheetId);
    }

    /** Take the sheet's next bulk settle batch number (1, 2, ...), in one statement so two users never get the same one. */
    public int nextSettleBatch(String sheetId) {
        return jdbc.queryForObject("SELECT last_settle_batch FROM FINAL TABLE "
                + "(UPDATE sheet SET last_settle_batch = last_settle_batch + 1 WHERE id = ?)", Integer.class, sheetId);
    }

    /**
     * Run the work in a transaction of its own (nested, to a savepoint, inside one already open), undoing every change
     * it made to the store when it answers false. Answers what the work answered.
     */
    public boolean keepOnly(BooleanSupplier work) {
        TransactionTemplate tx = new TransactionTemplate(new DataSourceTransactionManager(jdbc.getDataSource()));
        tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
        return Boolean.TRUE.equals(tx.execute(status -> {
            boolean keep = work.getAsBoolean();
            if (!keep) {
                status.setRollbackOnly();
            }
            return keep;
        }));
    }

    /** The number of the sheet's last bulk settle batch; null when there has been none. */
    public Integer lastSettleBatch(String sheetId) {
        return jdbc.query("SELECT last_settle_batch FROM sheet WHERE id = ?",
                rs -> rs.next() && rs.getInt(1) > 0 ? rs.getInt(1) : null, sheetId);
    }

    /** Mark the claim settled by the bulk settle batch. */
    public void markSettleBatch(Claim claim, int batch) {
        jdbc.update("UPDATE claim SET settle_batch = ? WHERE id = ?", batch, claim.getId());
        claim.setSettleBatch(batch);
    }

    /** Take the sheet's next claim number, in one statement so two users never get the same one. */
    public int nextNumber(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE "
                + "(UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)", Integer.class, sheetId);
    }

    /** Take the next number of one of the sheet's per-period sequences (a period's id, or X for no period), from 1. */
    public int nextNumber(String sheetId, String sequence) {
        try {
            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key) SELECT ?, ? FROM DUAL WHERE NOT EXISTS"
                    + " (SELECT 1 FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?)", sheetId, sequence, sheetId, sequence);
        } catch (org.springframework.dao.DuplicateKeyException started) {
            // another user started it first
        }
        return jdbc.queryForObject("SELECT last_number FROM FINAL TABLE (UPDATE claim_sequence SET last_number = last_number + 1"
                + " WHERE sheet_id = ? AND seq_key = ?)", Integer.class, sheetId, sequence);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.LateCharge;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.access.RoleRepository;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to the asked status, refusing a change its current status does not allow, an open, settle or void
 * the sheet's permission for it does not give the user's role, an open of a claim with an empty note whose due (as open) is above the
 * sheet's note threshold in force on the claim's date, and
 * refusing to let the user who opened it, or who last edited it, settle it; a clerk's settle whose due is above the sheet's
 * clerk limit in force on its today leaves it PENDING instead — but first, a settle or approve of a claim without a proof whose due is
 * above the proof threshold in force on the claim's date (its person's grade's on that date when set, else the sheet's) is refused (a due of n/a is within any limit; a steward settles anything). A review of a
 * PENDING claim is a steward's: approving settles it at its live due (never by the user who opened it or last edited it), rejecting
 * returns it to OPEN, bound again by its last statement if that bound it. A steward may void a SETTLED claim within
 * seven days of its settlement (its status log's last SETTLED date) by the sheet's today. While the sheet has void reasons,
 * a void needs one of them, kept on the claim. Opening records who opened it; a voided claim keeps its number. Settling
 * fixes the claim's due at the rate in force on the claim's date of its person's grade on that date — or, while a statement binds it, at
 * the figure it was bound to — with its late charge as of the sheet's today on top and then at least the sheet's floor in force on the claim's date, frozen in; without a figure its due stays live.
 */
public class ApplyClaimStatus {
    public void apply(@Val ClaimStatus status, @Val Claim claim, ClaimRepository repository,
            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
            PeriodRepository periods, ClaimLogRepository log, @Val ChangedBy by, @Val ClaimReview review, @Val VoidChoice voidChoice, VoidReasonRepository voidReasons,
            Out<ClaimNumber> audited) throws BadRequestException {
        ClaimStatus from = claim.getStatus();
        String role = roles.roleOf(claim.getSheetId(), by.name());
        boolean steward = Role.STEWARD.equals(role);
        if (review.asked()) {
            if (from != ClaimStatus.PENDING) {
                throw new BadRequestException("Only a PENDING claim is approved or rejected; this one is " + from);
            }
            if (!steward) {
                throw new BadRequestException("Only a steward approves or rejects a claim");
            }
            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
                throw new BadRequestException("The user who opened a claim cannot approve it");
            }
            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getEditedBy())) {
                throw new BadRequestException("The user who last edited a claim cannot approve it");
            }
        } else {
            if (!from.canBecome(status)) {
                throw new BadRequestException("A " + from + " claim cannot become " + status);
            }
            String action = status == ClaimStatus.OPEN ? "open" : status == ClaimStatus.VOID ? "void" : "settle";
            if (!settings.allows(claim.getSheetId(), action, role)) {
                throw new BadRequestException("A " + role + " may not " + action + " a claim on this sheet");
            }
            if (status == ClaimStatus.VOID && from == ClaimStatus.SETTLED) {
                if (!steward) {
                    throw new BadRequestException("Only a steward voids a SETTLED claim");
                }
                java.time.LocalDate settledOn = log.lastOn(claim.getSheetId(), claim.getId(), ClaimStatus.SETTLED);
                java.time.LocalDate today = sheets.today(claim.getSheetId());
                if (settledOn == null || today.isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
                    throw new BadRequestException("A SETTLED claim is voided only within "
                            + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement");
                }
            }
            if (status == ClaimStatus.VOID) {
                java.util.List<String> reasons = voidReasons.list(claim.getSheetId());
                if (!reasons.isEmpty() && voidChoice.reason() == null) {
                    throw new BadRequestException("Choose a void reason from the sheet's list");
                }
                if (voidChoice.reason() != null && !reasons.contains(voidChoice.reason())) {
                    throw new BadRequestException("That void reason is not on the sheet's list");
                }
            }
            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
                throw new BadRequestException("The user who opened a claim cannot settle it");
            }
            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getEditedBy())) {
                throw new BadRequestException("The user who last edited a claim cannot settle it");
            }
            if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
                throw new BadRequestException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
            }
        }
        LateCharge late = settings.lateCharge(claim.getSheetId(), sheets.today(claim.getSheetId()));
        BigDecimal due = status == ClaimStatus.SETTLED ? late.due(claim, dueNow(claim, people, rates, settings, late)) : null;
        if (status == ClaimStatus.OPEN && !review.asked() && (claim.getNote() == null || claim.getNote().isBlank())) {
            BigDecimal threshold = late.settings().noteThreshold(claim.getDate());
            BigDecimal opened = threshold == null ? null : late.dueAsOpen(claim, dueNow(claim, people, rates, settings, late));
            if (opened != null && opened.compareTo(threshold) > 0) {
                throw new BadRequestException("A claim whose due is above the note threshold needs a note before it is opened");
            }
        }
        if (status == ClaimStatus.SETTLED && due != null && claim.getProofs() == 0) {
            Person owner = people.find(claim.getSheetId(), claim.getPersonId());
            BigDecimal threshold = late.settings().proofThreshold(owner == null ? null : owner.gradeOn(claim.getDate()),
                    claim.getDate());
            if (threshold != null && due.compareTo(threshold) > 0) {
                throw new BadRequestException("A claim whose due is above the proof threshold needs a proof before it is settled");
            }
        }
        ClaimStatus to = status;
        if (!review.asked() && status == ClaimStatus.SETTLED && due != null && !steward) {
            BigDecimal limit = late.settings().clerkLimit(late.today());
            if (limit != null && due.compareTo(limit) > 0) {
                to = ClaimStatus.PENDING; // awaits a steward's approval
            }
        }
        claim.setStatus(to);
        if (to == ClaimStatus.VOID) {
            claim.setVoidReason(voidChoice.reason());
        }
        boolean opening = to == ClaimStatus.OPEN && !review.asked();
        if (opening) {
            claim.setOpenedBy(by.name());
        }
        if (to == ClaimStatus.SETTLED) {
            // A voided SETTLED claim keeps its frozen figure (shown, and reversed in its audit) but counts in no total.
            claim.setSettledDue(due);
        }
        if (!repository.updateStatus(claim, from)) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
        if (opening) {
            // Numbered only once the claim is surely moving, so a refused open uses up no number.
            claim.setNumber(number(claim, repository, settings, sheets, periods));
            repository.updateStatus(claim, to);
        }
        audited.set(new ClaimNumber(claim.getNumber()));
    }

    /**
     * The number an opened claim takes: while the sheet numbers by period and its today is on or after that setting's
     * date, the next within the claim's period (by its due-by) as {@code <period name>-<n>}, or {@code X-<n>} in no period;
     * otherwise the sheet's next.
     */
    static String number(Claim claim, ClaimRepository repository, SettingRepository settings,
            SheetRepository sheets, PeriodRepository periods) {
        String sheetId = claim.getSheetId();
        java.time.LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            return String.valueOf(repository.nextNumber(sheetId));
        }
        Period period = periods.on(sheetId, claim.getDueBy());
        return period == null ? "X-" + repository.nextNumber(sheetId, "X")
                : period.name() + "-" + repository.nextNumber(sheetId, String.valueOf(period.id()));
    }

    /** The figure a statement binds the claim to (not while PENDING), else the claim's amount times its person's grade's rate on the claim's date, rounded as the claim rounds by the sheet's policy date (not floored); null when there is no rate. */
    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates,
            SettingRepository settings, LateCharge late) {
        if (claim.isBound()) {
            return claim.getStatedDue();
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        return claim.figureAt(rate, late.rounding(claim));
    }
