385	public class ApplyClaimStatus {
386	    public void apply(@Val ClaimStatus status, @Val Claim claim, ClaimRepository repository,
387	            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
388	            PeriodRepository periods, ClaimLogRepository log, @Val ChangedBy by, @Val ClaimReview review, @Val VoidChoice voidChoice, VoidReasonRepository voidReasons,
389	            Out<ClaimNumber> audited) throws BadRequestException {
390	        ClaimStatus from = claim.getStatus();
391	        String role = roles.roleOf(claim.getSheetId(), by.name());
392	        boolean steward = Role.STEWARD.equals(role);
393	        if (review.asked()) {
394	            if (from != ClaimStatus.PENDING) {
395	                throw new BadRequestException("Only a PENDING claim is approved or rejected; this one is " + from);
396	            }
397	            if (!steward) {
398	                throw new BadRequestException("Only a steward approves or rejects a claim");
399	            }
400	            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
401	                throw new BadRequestException("The user who opened a claim cannot approve it");
402	            }
403	            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getEditedBy())) {
404	                throw new BadRequestException("The user who last edited a claim cannot approve it");
405	            }
406	        } else {
407	            if (!from.canBecome(status)) {
408	                throw new BadRequestException("A " + from + " claim cannot become " + status);
409	            }
410	            String action = status == ClaimStatus.OPEN ? "open" : status == ClaimStatus.VOID ? "void" : "settle";
411	            if (!settings.allows(claim.getSheetId(), action, role)) {
412	                throw new BadRequestException("A " + role + " may not " + action + " a claim on this sheet");
413	            }
414	            if (status == ClaimStatus.VOID && from == ClaimStatus.SETTLED) {
415	                if (!steward) {
416	                    throw new BadRequestException("Only a steward voids a SETTLED claim");
417	                }
418	                java.time.LocalDate settledOn = log.lastOn(claim.getSheetId(), claim.getId(), ClaimStatus.SETTLED);
419	                java.time.LocalDate today = sheets.today(claim.getSheetId());
420	                if (settledOn == null || today.isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
421	                    throw new BadRequestException("A SETTLED claim is voided only within "
422	                            + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement");
423	                }
424	            }
425	            if (status == ClaimStatus.VOID) {
426	                java.util.List<String> reasons = voidReasons.list(claim.getSheetId());
427	                if (!reasons.isEmpty() && voidChoice.reason() == null) {
428	                    throw new BadRequestException("Choose a void reason from the sheet's list");
429	                }
430	                if (voidChoice.reason() != null && !reasons.contains(voidChoice.reason())) {
431	                    throw new BadRequestException("That void reason is not on the sheet's list");
432	                }
433	            }
434	            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
435	                throw new BadRequestException("The user who opened a claim cannot settle it");
436	            }
437	            if (status == ClaimStatus.SETTLED && by.name().equals(claim.getEditedBy())) {
438	                throw new BadRequestException("The user who last edited a claim cannot settle it");
439	            }
440	            if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
441	                throw new BadRequestException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
442	            }
443	        }
444	        LateCharge late = settings.lateCharge(claim.getSheetId(), sheets.today(claim.getSheetId()));
445	        BigDecimal due = status == ClaimStatus.SETTLED ? late.due(claim, dueNow(claim, people, rates, settings, late)) : null;
446	        if (status == ClaimStatus.OPEN && !review.asked() && (claim.getNote() == null || claim.getNote().isBlank())) {
447	            BigDecimal threshold = late.settings().noteThreshold(claim.getDate());
448	            BigDecimal opened = threshold == null ? null : late.dueAsOpen(claim, dueNow(claim, people, rates, settings, late));
449	            if (opened != null && opened.compareTo(threshold) > 0) {
450	                throw new BadRequestException("A claim whose due is above the note threshold needs a note before it is opened");
451	            }
452	        }
453	        if (status == ClaimStatus.SETTLED && due != null && claim.getProofs() == 0) {
454	            Person owner = people.find(claim.getSheetId(), claim.getPersonId());
455	            BigDecimal threshold = late.settings().proofThreshold(owner == null ? null : owner.gradeOn(claim.getDate()),
456	                    claim.getDate());
457	            if (threshold != null && due.compareTo(threshold) > 0) {
458	                throw new BadRequestException("A claim whose due is above the proof threshold needs a proof before it is settled");
459	            }
460	        }
461	        ClaimStatus to = status;
462	        if (!review.asked() && status == ClaimStatus.SETTLED && due != null && !steward) {
463	            BigDecimal limit = late.settings().clerkLimit(late.today());
464	            if (limit != null && due.compareTo(limit) > 0) {
465	                to = ClaimStatus.PENDING; // awaits a steward's approval
466	            }
467	        }
468	        claim.setStatus(to);
469	        if (to == ClaimStatus.VOID) {
470	            claim.setVoidReason(voidChoice.reason());
471	        }
472	        boolean opening = to == ClaimStatus.OPEN && !review.asked();
473	        if (opening) {
474	            claim.setOpenedBy(by.name());
475	        }
476	        if (to == ClaimStatus.SETTLED) {
477	            // A voided SETTLED claim keeps its frozen figure (shown, and reversed in its audit) but counts in no total.
478	            claim.setSettledDue(due);
479	        }
480	        if (!repository.updateStatus(claim, from)) {
481	            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
482	        }
483	        if (opening) {
484	            // Numbered only once the claim is surely moving, so a refused open uses up no number.
485	            claim.setNumber(number(claim, repository, settings, sheets, periods));
486	            repository.updateStatus(claim, to);
487	        }
488	        audited.set(new ClaimNumber(claim.getNumber()));
489	    }
490	
491	    /**
492	     * The number an opened claim takes: while the sheet numbers by period and its today is on or after that setting's
493	     * date, the next within the claim's period (by its due-by) as {@code <period name>-<n>}, or {@code X-<n>} in no period;
494	     * otherwise the sheet's next.
495	     */
496	    static String number(Claim claim, ClaimRepository repository, SettingRepository settings,
497	            SheetRepository sheets, PeriodRepository periods) {
498	        String sheetId = claim.getSheetId();
499	        java.time.LocalDate from = settings.periodNumberingFrom(sheetId);
500	        if (from == null || sheets.today(sheetId).isBefore(from)) {
501	            return String.valueOf(repository.nextNumber(sheetId));
502	        }
503	        Period period = periods.on(sheetId, claim.getDueBy());
504	        return period == null ? "X-" + repository.nextNumber(sheetId, "X")
505	                : period.name() + "-" + repository.nextNumber(sheetId, String.valueOf(period.id()));
506	    }
507	
508	    /** The figure a statement binds the claim to (not while PENDING), else the claim's amount times its person's grade's rate on the claim's date, rounded as the claim rounds by the sheet's policy date (not floored); null when there is no rate. */
509	    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates,
510	            SettingRepository settings, LateCharge late) {
511	        if (claim.isBound()) {
512	            return claim.getStatedDue();
513	        }
514	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
515	        BigDecimal rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
516	        return claim.figureAt(rate, late.rounding(claim));
517	    }
518	}
519	package net.officefloor.hq.app.claim;
520	
521	import java.math.BigDecimal;
522	import java.math.RoundingMode;
523	import net.officefloor.hq.app.Audit;
524	import net.officefloor.hq.app.BadRequestException;
525	import net.officefloor.hq.app.access.RoleRepository;
526	import net.officefloor.hq.app.access.SettingRepository;
527	import net.officefloor.hq.app.period.PeriodRepository;
528	import net.officefloor.hq.app.person.Person;
529	import net.officefloor.hq.app.person.PersonRepository;
530	import net.officefloor.hq.app.person.WatchRepository;
531	import net.officefloor.hq.app.rate.RateRepository;
532	import net.officefloor.hq.app.rollup.Rollup;
533	import net.officefloor.hq.app.rollup.RollupSnapshot;
534	import net.officefloor.hq.app.session.ChangedBy;
535	import net.officefloor.hq.app.sheet.SheetRepository;
536	import net.officefloor.hq.app.sheet.SheetResponse;
537	import net.officefloor.hq.app.voidreason.VoidReasonRepository;
538	import net.officefloor.plugin.variable.Out;
539	import net.officefloor.plugin.variable.Val;
540	
541	/**
542	 * Settles the selected claims all or nothing. When every one can be settled, each is settled in list order — the
543	 * people in the order they were added, each one's claims newest first — exactly as settling it alone would (the same
544	 * audit and rollup lines; one a clerk's settle leaves PENDING counts as settled), the press is the sheet's next batch
545	 * and each claim carries its number, and a BATCH_SETTLED line follows with the count and the frozen figures of those
546	 * SETTLED added up. If any one would be refused (or is not on the sheet), none is settled, all count as refused and
547	 * nothing is written.
548	 */
549	public class SettleClaims {
550	    public void settle(@Val SheetResponse sheet, @Val BulkSettleIds selected, @Val ChangedBy by, ClaimRepository claims,
551	            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
552	            SheetRepository sheets, PeriodRepository periods, Rollup rollup, Audit audit, ClaimLog log, ClaimLogRepository logs, WatchRepository watches,
553	            VoidReasonRepository voidReasons,
554	            Out<BulkSettleResponse> result) {
555	        if (roles.isViewer(sheet.id(), by.name()) || sheets.isArchived(sheet.id())) {
556	            // A viewer's press, or one on an archived sheet, goes through with nothing done: every selected claim is
557	            // refused.
558	            result.set(new BulkSettleResponse(0, selected.ids().size()));
559	            return;
560	        }
561	        ApplyClaimStatus apply = new ApplyClaimStatus();
562	        RefuseClosedClaim closed = new RefuseClosedClaim();
563	        RecordClaimStatus record = new RecordClaimStatus();
564	        int[] counts = new int[1];
565	        BigDecimal[] total = { BigDecimal.ZERO };
566	        Integer[] batch = new Integer[1];
567	        audit.hold();
568	        boolean kept = false;
569	        try {
570	            kept = claims.keepOnly(() -> {
571	                for (Person person : people.list(sheet.id())) {
572	                    for (Claim claim : claims.listOf(sheet.id(), person.getId())) {
573	                        if (!selected.ids().contains(claim.getId())) {
574	                            continue;
575	                        }
576	                        try {
577	                            closed.check(claim, periods);
578	                            RollupSnapshot before = rollup.snapshot(sheet.id());
579	                            ClaimNumber[] number = new ClaimNumber[1];
580	                            Out<ClaimNumber> audited = value -> number[0] = value;
581	                            apply.apply(ClaimStatus.SETTLED, claim, claims, people, rates, roles, settings, sheets, periods, logs, by, ClaimReview.NONE, VoidChoice.NONE, voidReasons, audited);
582	                            record.record(claim, number[0], by, ClaimReview.NONE, people, watches, logs, audit, log);
583	                            rollup.record(sheet.id(), before, by);
584	                        } catch (BadRequestException refused) {
585	                            // One refusal refuses them all: nothing is settled or written.
586	                            return false;
587	                        }
588	                        if (batch[0] == null) {
589	                            batch[0] = claims.nextSettleBatch(sheet.id());
590	                        }
591	                        claims.markSettleBatch(claim, batch[0]);
592	                        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
593	                            total[0] = total[0].add(claim.getSettledDue());
594	                        }
595	                        counts[0]++;
596	                    }
597	                }
598	                // A selected id not on this sheet's list cannot be settled either.
599	                return counts[0] == selected.ids().size();
600	            });
601	            if (kept) {
602	                audit.record("BATCH_SETTLED sheet=" + sheet.id() + " by=" + by.name() + " batch=" + batch[0]
603	                        + " count=" + counts[0] + " total=" + total[0].setScale(2, RoundingMode.HALF_UP).toPlainString());
604	            }
605	        } finally {
606	            audit.release(kept);
607	        }
608	        int settled = kept ? counts[0] : 0;
609	        result.set(new BulkSettleResponse(settled, selected.ids().size() - settled));
610	    }
611	}
612	package net.officefloor.hq.app.claim;
613	
614	import java.math.BigDecimal;
615	import java.time.LocalDate;
616	import java.time.format.DateTimeParseException;
617	import net.officefloor.hq.app.BadRequestException;
618	import net.officefloor.hq.app.session.ChangedBy;
619	import net.officefloor.plugin.variable.Out;
620	import org.springframework.web.bind.annotation.RequestBody;
621	
622	/**
623	 * A claim's fields: an amount (required; a number with up to two decimals, 0.00 or more, or below 0.00
624	 * for a correction), a date (blank for the sheet's today), a note (may be empty) and the number of the
625	 * claim a correction corrects (blank for none) and an external reference (blank for none) and tags
626	 * (comma separated: each trimmed and lower-cased, repeats and blanks dropped, sorted; blank for none). Publishes them parsed, with the user making the change.
627	 */
628	public class ValidateClaim {
629	
630	    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> claim,
631	            Out<ChangedBy> changedBy) throws BadRequestException {
632	        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
633	        claim.set(parse(request));
634	        changedBy.set(by);
635	    }
636	
637	    /** The claim form's fields parsed under its rules; shared with every form that enters a claim's fields. */
638	    static ClaimInput parse(ClaimRequest request) throws BadRequestException {
639	        String date = request == null || request.date() == null ? "" : request.date().trim();
640	        String note = request == null || request.note() == null ? "" : request.note().trim();
641	        String ref = request == null || request.ref() == null ? "" : request.ref().trim();
642	        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
643	        BigDecimal amount = ClaimAmount.signed(request == null ? null : request.amount());
644	        LocalDate parsed = null;
645	        if (!date.isEmpty()) {
646	            try {
647	                parsed = LocalDate.parse(date);
648	            } catch (DateTimeParseException e) {
649	                throw new BadRequestException("Enter a date as YYYY-MM-DD");
650	            }
651	        }
652	        if (note.length() > 1000) {
653	            throw new BadRequestException("A note is at most 1000 characters");
654	        }
655	        if (ref.length() > 200) {
656	            throw new BadRequestException("A reference is at most 200 characters");
657	        }
658	        String tags = tags(request == null ? null : request.tags());
659	        if (tags != null && tags.length() > 1000) {
660	            throw new BadRequestException("Tags are at most 1000 characters");
661	        }
662	        String correctsNumber = null;
663	        if (!corrects.isEmpty()) {
664	            if (!corrects.matches("\\d{1,9}|.{1,200}-\\d{1,9}")) {
665	                throw new BadRequestException("Name the corrected claim by its number");
666	            }
667	            correctsNumber = corrects.matches("\\d+") ? String.valueOf(Integer.parseInt(corrects)) : corrects;
668	        }
669	        return new ClaimInput(amount, parsed, note, correctsNumber, ref.isEmpty() ? null : ref, tags);
670	    }
671	
672	    /** The tags as typed, normalised: sorted and joined by commas; null when there are none. */
673	    static String tags(String typed) {
674	        if (typed == null) {
675	            return null;
676	        }
677	        java.util.SortedSet<String> tags = new java.util.TreeSet<>();
678	        for (String tag : typed.split(",")) {
679	            String t = tag.trim().toLowerCase(java.util.Locale.ROOT);
680	            if (!t.isEmpty()) {
681	                tags.add(t);
682	            }
683	        }
684	        return tags.isEmpty() ? null : String.join(",", tags);
685	    }
686	}
