import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate, in force from its from-date (yyyy-mm-dd; null applies from the beginning of time) through its
 *  to-date (null: with no end). */
export type Rate = { grade: string; rate: string; from: string | null; to: string | null };

/** The key every feature reads the sheet's rates under. */
export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

/** The sheet's rates: each grade may have several, with different from-dates. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
  });
}

/**
 * The grade's rate in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or
 * before it, a rate without a from-date counting as the earliest. Undefined when none applies, or the date is
 * after that one's to-date.
 */
export function rateOn(rates: readonly Rate[], grade: string, date: string): Rate | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    // ISO dates compare as text; no from-date ('') sorts before every date.
    if (found === undefined || (r.from ?? '') > (found.from ?? '')) found = r;
  }
  return found !== undefined && found.to != null && found.to < date ? undefined : found;
}

/** A two-decimal number as a whole count of hundredths ("10.25" -> 1025n, "-1.03" -> -103n), exactly. */
export function toHundredths(text: string): bigint {
  const trimmed = text.trim();
  if (trimmed.startsWith('-')) return -toHundredths(trimmed.slice(1));
  const [whole, frac = ''] = trimmed.split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
}

/** Hundredths shown with two decimals. */
export function showHundredths(n: bigint): string {
  const sign = n < 0n ? '-' : '';
  const abs = n < 0n ? -n : n;
  return `${sign}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/**
 * Due, in cents, on an amount (in cents) at a rate (a percent, in hundredths): amount times rate
 * divided by 100, rounded to two decimals half to even (1.025 -> 1.02, 1.035 -> 1.04), or half up when
 * `halfUp` (1.025 -> 1.03). Rates are never negative; a correction's negative amount rounds the same way as
 * its size (-1.025 -> -1.02, half up -1.03).
 */
export function dueCents(amountCents: bigint, rateHundredths: bigint, halfUp = false): bigint {
  if (amountCents < 0n) return -dueCents(-amountCents, rateHundredths, halfUp);
  // cents * (rate/100 %) / 100 = cents * rateHundredths / 10000
  const exact = amountCents * rateHundredths;
  const whole = exact / 10000n;
  const rest = exact % 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n))) return whole + 1n;
  return whole;
}

/** The late charge's terms as of the sheet's today: its late percent (in hundredths) in force on a date; a grade's
 *  grace (days) in force on a date; and
 *  the sheet's policy date (its today when blank) with the date of each numbered claim, which decide how a claim's
 *  live figures round. */
export type Late = { today: string; pctOn: (date: string) => bigint; graceOn: (grade: string | undefined, date: string) => number; policyDate: string;
  dateOfNumber: ReadonlyMap<string, string> };

/** Whether the claim's live figures round half up: it (or, for a correction, the claim it corrects) is dated before
 *  the sheet's policy date; on or after it they round half to even. Half to even until the sheet's today is known. */
export function roundsHalfUp(late: Late | undefined, claim: { date: string; corrects?: string | null }): boolean {
  if (late === undefined) return false;
  const on = (claim.corrects != null ? late.dateOfNumber.get(claim.corrects) : undefined) ?? claim.date;
  return on < late.policyDate;
}

/** A date (yyyy-mm-dd) plus a number of days, as yyyy-mm-dd. */
export function addDays(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** The days from one date (yyyy-mm-dd) to another. */
function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

/** Whether a claim is a correction: its amount is below 0.00. A correction has no floor and no late charge. */
export function isCorrection(claim: { amount: string }): boolean {
  return claim.amount.trim().startsWith('-') && toHundredths(claim.amount.trim().slice(1)) > 0n;
}

/** Whether a claim is still live and payable: OPEN, or PENDING a steward's approval of its settle. */
export function isOpen(claim: { status: string }): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Whether the person's last statement binds the claim to its `statedDue`: it was stated, and is not PENDING (a PENDING
 *  claim shows and totals its live figure; rejected back to OPEN, it is bound again). */
export function isBound(claim: { stated: boolean; status?: string }): boolean {
  return claim.stated && claim.status !== 'PENDING';
}

/** The date a claim's lateness counts from: its due-by plus the grace in force on its date of its person's grade on
 *  that date (none while blank). Overdue once this is before the sheet's today; the 30-day boundaries count from it. */
export function lateFrom(late: Late | undefined, grade: string | undefined, claim: { date: string; dueBy: string }): string {
  const grace = late === undefined ? 0 : late.graceOn(grade, claim.date);
  return grace === 0 ? claim.dueBy : addDays(claim.dueBy, grace);
}

/** A claim's late charge in cents on its figure: for an OPEN (or PENDING) claim past its due-by (the terms-th business day after its date, by the terms fixed when it was added and the sheet's holidays now)
 *  plus its grade's grace (see lateFrom), for every
 *  full 30 days it is overdue, the late percent in force on that boundary date (that date plus 30, 60, 90 ... days) of the figure
 *  plus the charges of the boundaries before it (compounding), each rounded as the claim rounds (roundsHalfUp), the charges added up; otherwise (or for a correction,
 *  or a claim deferred past the sheet's today) 0. */
export function lateCents(late: Late | undefined, claim: { amount: string; date: string; status: string; dueBy: string; corrects?: string | null;
  deferred?: boolean }, figureCents: bigint, grade?: string): bigint {
  if (late === undefined || !isOpen(claim) || isCorrection(claim) || claim.deferred) return 0n;
  const from = lateFrom(late, grade, claim);
  const overdue = daysBetween(from, late.today);
  const periods = overdue > 0 ? BigInt(Math.floor(overdue / 30)) : 0n;
  let charge = 0n;
  for (let n = 1n; n <= periods; n++) {
    const pct = late.pctOn(addDays(from, Number(n) * 30));
    if (pct !== 0n) charge += dueCents(figureCents + charge, pct, roundsHalfUp(late, claim));
  }
  return charge;
}

/** A claim's due figure in cents: fixed when it was settled; while a statement binds it, the figure it was bound to;
 *  otherwise (or while it is PENDING) its amount times its person's grade's rate
 *  in force on the claim's date, rounded half to even (half up when `halfUp`). The floor is not applied here (see
 *  claimDueCents). Null when there is no figure (no rate of the grade then). */
export function claimFigureCents(rates: readonly Rate[], grade: string | undefined,
  claim: { amount: string; date: string; status?: string; settledDue: string | null; stated: boolean; statedDue: string | null },
  halfUp = false): bigint | null {
  if (claim.settledDue != null) return toHundredths(claim.settledDue);
  if (isBound(claim)) return claim.statedDue == null ? null : toHundredths(claim.statedDue);
  const found = grade === undefined ? undefined : rateOn(rates, grade, claim.date);
  if (found === undefined) return null;
  const correction = isCorrection(claim);
  const amount = toHundredths(correction ? claim.amount.trim().slice(1) : claim.amount);
  return dueCents(correction ? -amount : amount, toHundredths(found.rate), halfUp);
}

/** A claim's due in cents: fixed when it was settled; otherwise the greater of the sheet's floor in force on the
 *  claim's date and its figure (claimFigureCents: the rate figure, or the one a statement bound) with its late charge
 *  on top while it is overdue. The charge and the floor are never bound by a statement; a correction has neither.
 *  Null without a figure. */
export function claimDueCents(rates: readonly Rate[], grade: string | undefined,
  claim: { amount: string; date: string; status: string; settledDue: string | null; stated: boolean; statedDue: string | null;
    dueBy: string; corrects?: string | null; deferred?: boolean },
  floorOn: (date: string) => bigint, late: Late | undefined): bigint | null {
  const figure = claimFigureCents(rates, grade, claim, roundsHalfUp(late, claim));
  if (figure == null) return null;
  if (claim.settledDue != null) return figure;
  const due = figure + lateCents(late, claim, figure, grade);
  if (isCorrection(claim)) return due;
  const floor = floorOn(claim.date);
  return due >= floor ? due : floor;
}

/** Figures added up, leaving out the single highest and the single lowest when there are three or more. */
export function trimmedSum(figures: bigint[]): bigint {
  let sum = 0n;
  for (const f of figures) sum += f;
  if (figures.length < 3) return sum;
  const max = figures.reduce((a, b) => (b > a ? b : a));
  const min = figures.reduce((a, b) => (b < a ? b : a));
  return sum - max - min;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import type { Holds } from '../people/people.slot';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when the claim is opened: the sheet's next (1, 2, ...), or within its period (<period>-<n>, X-<n> in none); none for a draft. */
  number: string | null;
  /** The due fixed when the claim was settled; none while live (not settled, or settled without a rate). */
  settledDue: string | null;
  /** The signed-in user who opened the claim; none when it was never opened. They cannot settle it. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim: it then shows and totals `statedDue` (none: n/a). */
  stated: boolean;
  statedDue: string | null;
  /** The number of the SETTLED claim this correction (a negative amount) corrects; none for any other claim. */
  corrects: string | null;
  /** The date the claim is due by: the terms-th business day after its date when added (skipping Saturdays, Sundays and the sheet's holidays now), by the terms fixed then. */
  dueBy: string;
  /** The claim's status log, oldest first: `<STATUS> by <user> on <date> due=<due>`. */
  log: string[];
  /** Whether the OPEN claim is deferred past the sheet's today: it then counts in no total, is not overdue and cannot be settled. */
  deferred: boolean;
  /** The date it was last deferred until; none when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs the claim carries; one above the proof threshold needs one before it is settled or approved. */
  proofs: number;
  /** The number of the claim this one was split off; none when it was not split off one. */
  splitFrom: string | null;
  /** Whether it was added while the period containing its due-by was soft-closed. */
  lateEntry: boolean;
  /** The last sheet-today a reminder was written for the claim; none when it was never reminded. */
  reminded: string | null;
  /** The claim's external reference, used at most once on the sheet (case aside); none when it has none. */
  ref: string | null;
  /** The claim's tags, sorted; empty when it has none. */
  tags: string[];
  /** The reason the claim was voided with, from the sheet's list; none when none was given. */
  voidReason: string | null;
  /** The claim's comments, oldest first: `<user> on <date>: <text>` (the sheet's today when written). */
  comments: string[];
  /** The number of the bulk settle batch that settled the claim; none when no batch settled it. */
  settleBatch: number | null };

/** Whether a claim counts toward claimed, due and every total: only OPEN, PENDING and SETTLED claims do, and an OPEN
 *  or PENDING one dated within one of its person's holds (`held`: each person's holds) does not unless a statement binds it;
 *  nor does one deferred past the sheet's today. */
export function counts(claim: { status: ClaimStatus; personId: number; date: string; stated: boolean; deferred?: boolean }, held: Holds): boolean {
  if (claim.deferred) return false;
  if (claim.status === 'OPEN' || claim.status === 'PENDING') {
    return claim.stated || !(held.get(claim.personId) ?? []).some((h) =>
      (h.from === null || h.from <= claim.date) && (h.to === null || claim.date <= h.to));
  }
  return claim.status === 'SETTLED';
}

/** The key every feature reads the sheet's claims under. */
export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** The key of a claim editor's lock request: a claim form waits for it before it submits. */
export const claimLockKey = (sheetId: string) => ['sheet', sheetId, 'claim-lock'] as const;

/** The key of a claim form's save: saving a claim's editor clears the claim's lock refusal. */
export const claimSaveKey = (sheetId: string) => ['sheet', sheetId, 'claim-save'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** Every tag ever used on the sheet's claims, sorted; under the claims' key, so whatever refreshes the claims refreshes it. */
export function useClaimTags(sheetId: string) {
  return useQuery({
    queryKey: [...claimsKey(sheetId), 'tags'] as const,
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/tags`),
  });
}

/** The number of the sheet's last bulk settle batch (none when there has been none); under the claims' key, so
 *  whatever refreshes the claims refreshes it. */
export function useLastSettleBatch(sheetId: string) {
  return useQuery({
    queryKey: [...claimsKey(sheetId), 'settle-batch'] as const,
    queryFn: () => getJson<{ batch: number | null }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/settle-batch`),
  });
}

/** Which claim's editor is open (search param `editClaim`); none means each claim form adds. */
export function useEditingClaim() {
  return useSearchParam('editClaim', asNumber);
}

/** The counted claims' amounts added up exactly, in cents, shown with two decimals. */
export function sumAmounts(claims: Claim[], held: Holds): string {
  const cents = claims.filter((c) => counts(c, held)).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { toHundredths, type Late } from '../rates/useRates';
import { useSheetToday } from '../today/today.slot';
import { useClaims } from '../claims/useClaims';

/** A role assigned to a user name: clerk (any name without one), steward or viewer. */
export type Role = { user: string; role: string };

/** A sheet setting: its value in force on the sheet's today (null: blank) and, for a dated one, every value recorded
 *  by from-date (yyyy-mm-dd), each in force until the next one's. */
export type Setting = { key: string; value: string | null; dated: { from: string; value: string | null }[] };

/** A dated setting's value in force on a date (yyyy-mm-dd): the one with the latest from-date on or before it; before
 *  every from-date (or when blank), `starting`. */
export function settingOn(setting: Setting | undefined, date: string, starting: string): string {
  let found: { from: string; value: string | null } | undefined;
  for (const d of setting?.dated ?? []) {
    // ISO dates compare as text.
    if (d.from <= date && (found === undefined || d.from > found.from)) found = d;
  }
  return found?.value ?? starting;
}

/** A steward's (`by`) delegation of the steward role to a user, from a date to a date (yyyy-mm-dd), both inclusive. */
export type Delegation = { user: string; from: string; to: string; by: string };

export const delegationsKey = (sheetId: string) => ['sheet', sheetId, 'delegations'] as const;

/** The sheet's delegations of the steward role, in the order they were made. */
export function useDelegations(sheetId: string) {
  return useQuery({
    queryKey: delegationsKey(sheetId),
    queryFn: () => getJson<Delegation[]>(`/api/sheets/${encodeURIComponent(sheetId)}/delegations`),
  });
}

export const rolesKey = (sheetId: string) => ['sheet', sheetId, 'roles'] as const;
export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;

/** The sheet's assigned roles, by user name. */
export function useRoles(sheetId: string) {
  return useQuery({
    queryKey: rolesKey(sheetId),
    queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
  });
}

/** The floor a sheet starts with, until it is set. */
export const FLOOR_DEFAULT = '1.00';

/** The sheet's settings, by key. */
export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Setting[]>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/** The sheet's floor in cents in force on a date: the least a claim's live due may be (1.00 before any is in force). */
export type FloorOn = (date: string) => bigint;

/** The sheet's floor in cents, by the date it is in force on. */
export function useFloorCents(sheetId: string): FloorOn {
  const floor = useSettings(sheetId).data?.find((s) => s.key === 'floor');
  return (date) => toHundredths(settingOn(floor, date, FLOOR_DEFAULT));
}

/** The sheet's cap in cents in force on its today: the most a person's due-total may be; null while blank (no cap). */
export function useCapCents(sheetId: string): bigint | null {
  const value = useSettings(sheetId).data?.find((s) => s.key === 'cap')?.value;
  return value == null || value === '' ? null : toHundredths(value);
}

/** The terms a sheet starts with, until they are set: the days after its date a claim is due by. */
export const TERMS_DEFAULT = '14';

/** The late percent a sheet starts with, until it is set. */
export const LATE_PCT_DEFAULT = '0.00';

/** The sheet's late charge as of its today: its late percent in force on each date (0.00 before any is), and each
 *  grade's grace in force on a date (0 while blank); with its
 *  policy date (its today while blank) and the numbered claims' dates, which decide how each claim rounds. Undefined
 *  until the sheet's today is known. */
export function useLate(sheetId: string): Late | undefined {
  const settings = useSettings(sheetId).data;
  const pct = settings?.find((s) => s.key === 'late-pct');
  const policy = settings?.find((s) => s.key === 'policy-date')?.value ?? '';
  const today = useSheetToday(sheetId).data?.today;
  const claims = useClaims(sheetId).data;
  const dateOfNumber = new Map<string, string>();
  for (const c of claims ?? []) if (c.number != null) dateOfNumber.set(c.number, c.date);
  const graceOn = (grade: string | undefined, date: string) => {
    const value = grade === undefined ? '' : settingOn(settings?.find((s) => s.key === `grace-${grade}`), date, '');
    return value === '' ? 0 : Number(value);
  };
  return today === undefined ? undefined
    : { today, pctOn: (date) => toHundredths(settingOn(pct, date, LATE_PCT_DEFAULT)), graceOn,
      policyDate: policy === '' ? today : policy, dateOfNumber };
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/useClaims';
import { usePeople } from '../people/people.slot';
import { showPeriodDueTotal, usePeriodDueTotal, usePeriods } from '../periods/periods.slot';
import { useIsActive } from '../active/active.slot';
import { useDueTotals } from '../rates/rates.slot';
import { showHundredths } from '../rates/useRates';
import { useVoidReasons } from '../voidreasons/voidReasons.slot';

const GRADES = ['A', 'B', 'C'] as const;
