            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {[...sums.keys()].sort().map((m) => (
            <tr key={m}>
              <td>{m}</td>
              <td data-testid={`month-${m}-due-total`}>{showHundredths(sums.get(m) ?? 0n)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

