import { ClaimCells } from '../../slots/defs/claimRow';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useFloorCents, useLate } from '../access/useAccess';
import { counts, useClaims } from '../claims/useClaims';
import { gradeOn, useHeld, usePeople } from '../people/people.slot';
import { claimDueCents, isOpen, lateFrom, showHundredths, trimmedSum, useRates } from '../rates/useRates';
import { useSheetToday } from '../today/today.slot';

/** Whether a claim is overdue: OPEN or PENDING, not deferred past the sheet's today, and its due-by plus its grade's
 *  grace (see lateFrom; `grade` is its person's grade on its date) before the sheet's today. */
function useIsOverdue(sheetId: string): (claim: { status: string; date: string; dueBy: string; deferred?: boolean }, grade: string | undefined) => boolean {
  const today = useSheetToday(sheetId).data?.today;
  const late = useLate(sheetId);
  return (claim, grade) => today !== undefined && isOpen(claim) && !claim.deferred && lateFrom(late, grade, claim) < today;
}

type Overdue = { count: number; cents: bigint };

/** The overdue claims that count, per person and for the sheet: how many, and their due (late charge included) added up (n/a as 0);
 *  the sheet's total leaves out the single highest and the single lowest person's when there are three or more people. */
export function useOverdue(sheetId: string): { byPerson: Map<number, Overdue>; sheet: Overdue } {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const held = useHeld(sheetId);
  const floor = useFloorCents(sheetId);
  const late = useLate(sheetId);
  const isOverdue = useIsOverdue(sheetId);
  const byPerson = new Map<number, Overdue>();
  const sheet: Overdue = { count: 0, cents: 0n };
  for (const p of people.data ?? []) {
    const mine: Overdue = { count: 0, cents: 0n };
    for (const c of claims.data ?? []) {
      if (c.personId !== p.id || !counts(c, held) || !isOverdue(c, gradeOn(p, c.date))) continue;
      mine.count += 1;
      mine.cents += claimDueCents(rates.data ?? [], gradeOn(p, c.date), c, floor, late) ?? 0n;
    }
    byPerson.set(p.id, mine);
    sheet.count += mine.count;
  }
  sheet.cents = trimmedSum([...byPerson.values()].map((o) => o.cents));
  return { byPerson, sheet };
}

function OverdueHeads() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

// A person's overdue count and overdue-total: their counted OPEN claims past their due-by, and those claims' due added up.
function OverdueCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const mine = useOverdue(sheetId).byPerson.get(personId) ?? { count: 0, cents: 0n };
  return (
    <>
      <td data-testid="person-overdue-count">{mine.count}</td>
      <td data-testid="person-overdue-total">{showHundredths(mine.cents)}</td>
    </>
  );
}

// A claim's due-by (the terms-th business day after its date, by the terms fixed when it was added and the sheet's holidays now) and whether it is overdue (OPEN and due-by plus its grade's grace before the sheet's today).
function ClaimOverdue({ sheetId, personId, claim }: { sheetId: string; user: string; personId: number; claim: { status: string; date: string; dueBy: string; deferred?: boolean } }) {
  const isOverdue = useIsOverdue(sheetId);
  const person = usePeople(sheetId).data?.find((p) => p.id === personId);
  return (
    <>
      Due by <span data-testid="claim-due-by">{claim.dueBy}</span>{' '}
      Overdue <span data-testid="claim-overdue">{isOverdue(claim, gradeOn(person, claim.date)) ? 'yes' : 'no'}</span>{' '}
    </>
  );
}

// The sheet's overdue count and overdue-total: everyone's added up.
function OverdueTotal({ sheetId }: { sheetId: string; user: string }) {
  const { sheet } = useOverdue(sheetId);
  return (
    <section data-testid="overdue-rollup">
      <p>
        Overdue: <strong data-testid="rollup-overdue-count">{sheet.count}</strong>{' '}
        Overdue total: <strong data-testid="rollup-overdue-total">{showHundredths(sheet.cents)}</strong>
      </p>
    </section>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 25, Component: OverdueHeads }),
  PersonCells.fill({ order: 25, Component: OverdueCells }),
  ClaimCells.fill({ order: 12, Component: ClaimOverdue }),
  SheetBody.fill({ order: 26, Component: OverdueTotal }),
];
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { useFloorCents, useLate } from '../access/useAccess';
import { counts, useClaims } from '../claims/useClaims';
import { gradeOn, useHeld, usePeople } from '../people/people.slot';
import { claimDueCents, isOpen, showHundredths, useRates } from '../rates/useRates';
import { useSheetToday } from '../today/today.slot';

type Aged = { upTo30: bigint; upTo60: bigint; over60: bigint };

const DAY_MS = 24 * 60 * 60 * 1000;

/** The days from a claim's date to the sheet's today (negative when it is dated after today). */
function ageInDays(date: string, today: string): number {
  return Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${date}T00:00:00Z`)) / DAY_MS);
}

/** Each person's due (late charge included, n/a as 0) of their counted OPEN and PENDING claims, split by the claim's age on
 *  the sheet's today: 0 to 30 days (a claim dated after today included), 31 to 60, and 61 or more. */
export function useAged(sheetId: string): Map<number, Aged> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const held = useHeld(sheetId);
  const floor = useFloorCents(sheetId);
  const late = useLate(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const byPerson = new Map<number, Aged>();
  for (const p of people.data ?? []) {
    const mine: Aged = { upTo30: 0n, upTo60: 0n, over60: 0n };
    for (const c of claims.data ?? []) {
      if (today === undefined || c.personId !== p.id || !isOpen(c) || !counts(c, held)) continue;
      const due = claimDueCents(rates.data ?? [], gradeOn(p, c.date), c, floor, late) ?? 0n;
      const age = ageInDays(c.date, today);
      if (age <= 30) mine.upTo30 += due;
      else if (age <= 60) mine.upTo60 += due;
      else mine.over60 += due;
    }
    byPerson.set(p.id, mine);
  }
  return byPerson;
}

function AgedHeads() {
  return (
    <>
      <th>Aged 0–30</th>
      <th>Aged 31–60</th>
      <th>Aged 61+</th>
    </>
  );
}

// A person's due of their counted OPEN and PENDING claims, by the claim's age on the sheet's today.
function AgedCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const mine = useAged(sheetId).get(personId) ?? { upTo30: 0n, upTo60: 0n, over60: 0n };
  return (
    <>
      <td data-testid="person-aged-0-30">{showHundredths(mine.upTo30)}</td>
      <td data-testid="person-aged-31-60">{showHundredths(mine.upTo60)}</td>
      <td data-testid="person-aged-61">{showHundredths(mine.over60)}</td>
    </>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 26, Component: AgedHeads }),
  PersonCells.fill({ order: 26, Component: AgedCells }),
];
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { counts, useClaims } from '../claims/useClaims';
import { useHeld } from '../people/people.slot';
import { addDays } from '../rates/useRates';
import { useSheetToday } from '../today/today.slot';

/** Whether a person is active: they have an OPEN or PENDING claim that counts, dated within the 30 days up to and
 *  including the sheet's today. */
export function useIsActive(sheetId: string): (personId: number) => boolean {
  const today = useSheetToday(sheetId).data?.today;
  const claims = useClaims(sheetId);
  const held = useHeld(sheetId);
  const from = today === undefined ? undefined : addDays(today, -29);
  return (personId) => today !== undefined && from !== undefined && (claims.data ?? []).some((c) =>
    c.personId === personId && (c.status === 'OPEN' || c.status === 'PENDING') && counts(c, held)
    && from <= c.date && c.date <= today);
}

function ActiveHead() {
  return <th>Active</th>;
}

// Whether the person is active: an OPEN or PENDING counting claim dated within the last 30 days.
function ActiveCell({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const isActive = useIsActive(sheetId);
  return <td data-testid="person-active">{isActive(personId) ? 'yes' : 'no'}</td>;
}

export const contributions = [
  PersonHeads.fill({ order: 27, Component: ActiveHead }),
  PersonCells.fill({ order: 27, Component: ActiveCell }),
];
import { useState, type ChangeEvent } from 'react';
import { useIsMutating, useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimRow';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/useSession';
import { useHeld } from '../people/people.slot';
import { claimLockKey, claimSaveKey, claimsKey, sumAmounts, useClaims, useEditingClaim, type Claim } from './useClaims';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';
const AMOUNT = /^-?\d+(\.\d{1,2})?$/;
type ClaimBody = { amount: string; date: string; note: string; corrects: string; ref: string; tags: string };
// A person's claim form: adds a claim, or — with one of their claims' editor open — saves its
// changes. It is re-mounted for each claim opened, so it starts filled with that claim's values.
function ClaimForm({ sheetId, personId, editing }: { sheetId: string; personId: number; editing?: Claim }) {
  const [, setEditing] = useEditingClaim();
  const [amount, setAmount] = useState(editing?.amount ?? '');
  const [date, setDate] = useState(editing?.date ?? '');
  const [note, setNote] = useState(editing?.note ?? '');
  const [corrects, setCorrects] = useState(editing?.corrects ?? '');
  const [ref, setRef] = useState(editing?.ref ?? '');
  const [tags, setTags] = useState(editing?.tags.join(', ') ?? '');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const sheet = `/api/sheets/${encodeURIComponent(sheetId)}`;
  const save = useMutation({
    mutationKey: claimSaveKey(sheetId),
    mutationFn: async (body: ClaimBody) => {
      if (body.amount.trim() === '') throw new Error('Enter an amount');
      if (!AMOUNT.test(body.amount.trim())) throw new Error('An amount is a number with up to two decimals');
      // `by` is the signed-in user the change is recorded against.
      const sent = { ...body, by: user ?? '' };
      return editing
        ? putJson<Claim>(`${sheet}/claims/${editing.id}`, sent)
        : postJson<Claim>(`${sheet}/people/${personId}/claims`, sent);
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      if (editing) {
        setEditing(undefined);
      } else {
        setAmount('');
        setDate('');
        setNote('');
        setCorrects('');
        setRef('');
        setTags('');
      }
    },
  });
  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
  };
  // While a claim's editor is being opened, the form may be about to become its editor: it waits.
  const locking = useIsMutating({ mutationKey: claimLockKey(sheetId) }) > 0;
  const submit = useSubmitOnce(save);
  return (
    <form
      data-testid="claim-form"
      onSubmit={(e) => {
        e.preventDefault();
        submit({ amount, date, note, corrects, ref, tags });
      }}
    >
      <input data-testid="claim-form-amount" placeholder="Amount" inputMode="decimal" value={amount} onChange={field(setAmount)} />{' '}
      <input data-testid="claim-form-date" type="date" value={date} onChange={field(setDate)} />{' '}
      <input data-testid="claim-form-note" placeholder="Note" value={note} onChange={field(setNote)} />{' '}
      <input data-testid="claim-form-corrects" placeholder="Corrects no." value={corrects} onChange={field(setCorrects)} />{' '}
      <input data-testid="claim-form-ref" placeholder="Reference" value={ref} onChange={field(setRef)} />{' '}
      <input data-testid="claim-form-tags" placeholder="Tags, comma separated" value={tags} onChange={field(setTags)} />{' '}
      <button type="submit" data-testid="claim-form-submit" disabled={save.isPending || locking}>
        {editing ? 'Save claim' : 'Add claim'}
      </button>
      {save.isError && (
        <p data-testid="claim-form-error" role="alert">
          {save.error.message}
        </p>
      )}
    </form>
  );
}
function ClaimsHead() {
  return (
    <>
      <th>Claimed</th>
      <th>Claims</th>
    </>
  );
}
// A person's claimed total, and their claims, newest first, under the form that adds or edits them. A claim's edit and
// cancel buttons are in its status cell, with its locking.
function ClaimsCells({ sheetId, user, personId }: { sheetId: string; user: string; personId: number }) {
  const claims = useClaims(sheetId);
  const [editingId] = useEditingClaim();
  const held = useHeld(sheetId);
  const mine = (claims.data ?? []).filter((c) => c.personId === personId);
  const editing = mine.find((c) => c.id === editingId);
  return (
    <>
      <td data-testid="person-claimed">{sumAmounts(mine, held)}</td>
      <td>
        <ClaimForm key={editing ? `edit-${editing.id}` : 'add'} sheetId={sheetId} personId={personId} editing={editing} />
        <ul data-testid="claim-list">
          {mine.map((c) => (
            <li key={c.id} data-testid={`claim-row-${c.id}`}>
              <span data-testid="claim-amount">{Number(c.amount).toFixed(2)}</span>{' '}
              <span data-testid="claim-date">{c.date}</span>{' '}
              <span data-testid="claim-note">{c.note}</span>{' '}
              <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
              <span data-testid="claim-ref">{c.ref ?? ''}</span>{' '}
              <span data-testid="claim-tags">{c.tags.join(', ')}</span>{' '}
              <ClaimCells.Slot sheetId={sheetId} user={user} personId={personId} claim={c} />
            </li>
          ))}
        </ul>
      </td>
    </>
  );
}
// The sheet's claimed-total: everyone's counted claims added up.
function ClaimedTotal({ sheetId }: { sheetId: string; user: string }) {
  const claims = useClaims(sheetId);
  const held = useHeld(sheetId);
  return (
    <section data-testid="claims-rollup">
      <p>
        Claimed total: <strong data-testid="rollup-claimed-total">{sumAmounts(claims.data ?? [], held)}</strong>
      </p>
      {claims.isError && (
        <p data-testid="claims-error" role="alert">
          {claims.error.message}
        </p>
      )}
    </section>
  );
}
export const contributions = [
  PersonHeads.fill({ order: 10, Component: ClaimsHead }),
  PersonCells.fill({ order: 10, Component: ClaimsCells }),
  SheetBody.fill({ order: 20, Component: ClaimedTotal }),
];

