function PatronHeads() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th />
    </>
  );
}
// The person's patrons (names, sorted), their backing — the patrons' SETTLED claims dated within the 90 days up to and
// including the sheet's today, each at its frozen figure, added up (0.00 with none) — and the picker that names one more. Only other people not yet their patrons are offered. A refusal shows on
// the person until the picker is changed or the next action on their row.
function PatronCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const people = usePeople(sheetId).data ?? [];
  const person = people.find((p) => p.id === personId);
  const claims = useClaims(sheetId).data ?? [];
  const today = useSheetToday(sheetId).data?.today;
  const [chosen, setChosen] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationKey: personActionKey(sheetId, personId),
    mutationFn: async (patron: string) => {
      if (patron === '') throw new Error('Choose a patron');
      return postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/patrons`, {
        patron: Number(patron),
        by: user ?? '',
      });
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      setChosen('');
    },
  });
  const last = useLastPersonAction(sheetId, personId, add.submittedAt);
  const patrons = person?.patrons ?? [];
  const offered = people.filter((p) => p.id !== personId && !patrons.includes(p.name));
  let backing = 0n;
  if (today !== undefined) {
    const since = addDays(today, -89);
    const patronIds = new Set(people.filter((p) => patrons.includes(p.name)).map((p) => p.id));
    for (const c of claims) {
      if (!patronIds.has(c.personId) || c.status !== 'SETTLED' || c.settledDue == null) continue;
      if (c.date < since || c.date > today) continue;
      backing += toHundredths(c.settledDue);
    }
  }
  const people = usePeople(sheetId);
  const [editingId, setEditing] = useEditingClaim();
  const periods = usePeriods(sheetId);
  const roles = useRoles(sheetId);
  const delegations = useDelegations(sheetId);
  const sheetToday = useSheetToday(sheetId);
  // An edit the screen can already tell is refused shows its refusal at once, before any request: the claim form must
  // not be taken for its editor. The server refuses the same edits (and any it alone can tell).
  const [refused, setRefused] = useState<string>();
  // A viewer's edit is refused too, but its editor opens (to be cancelled), as for a lock another user holds.
  // One a steward's delegation holds on the sheet's today acts as a steward, as the server decides.
  const viewer = () => {
    const assigned = roles.data ?? [];
    const steward = (name: string) => assigned.some((r) => r.user === name && r.role === 'steward');
    const today = sheetToday.data?.today;
    const acting = today !== undefined && (delegations.data ?? []).some((d) =>
      d.user === user && steward(d.by) && d.from <= today && today <= d.to);
    return !acting && assigned.some((r) => r.user === user && r.role === 'viewer');
  };
  const refusal = (): string | undefined => {
    if (viewer()) return 'A viewer may not change anything on this sheet';
    if (claim.status !== 'DRAFT') return 'Only a DRAFT claim can be edited; void it and add a new one instead';
    if (periodOn(periods.data ?? [], claim.dueBy)?.closed) return "That claim's date is in a closed period";
    return undefined;
  };
  const base = `/api/sheets/${encodeURIComponent(sheetId)}/claims`;

